    using Structures.World;

    /// <summary>
    /// 790 spawn pools on the mined areas of thirteen zones: camp 133, lair 70, nest 131, outpost 35, post 302, squad 119.
    /// 
    /// Abyss 30 pools / 7 creatures; Ashen Desert 67 pools / 10 creatures; Crucible 38 pools / 6 creatures; Descent 34 pools / 5 creatures; Howling Maw 57 pools / 8 creatures; Incline 55 pools / 8 creatures; Marshes 97 pools / 10 creatures; Mires 81 pools / 8 creatures; Palisades 75 pools / 10 creatures; Plains 70 pools / 9 creatures; Plateau 56 pools / 7 creatures; Pools 32 pools / 9 creatures; Thunderhead 98 pools / 9 creatures.
    /// 
    /// Position and radius come from the client's own map placements (spawn_areas.csv): the pool sits on
    /// the centroid of a Bane camp's kit or a creature lair's, its radius the 90th percentile of the kit's
    /// spread clamped per size (post 6-20, squad 5-12, camp 8-30, outpost 10-40, nest 6-15, lair 8-20).
    /// Bane composition per size: post soldier 2-3 grenadier 0-1; squad soldier 2-3 grenadier 1 caretaker
    /// 0-1; camp soldier 2-3 grenadier 1-2 technician 1 caretaker 1; outpost soldier 3-4 grenadier 2
    /// technician 1-2 caretaker 1-2 commander 1 shield drone 0-1; every third camp trades grenadiers for the
    /// zone's first specialist, every fourth outpost adds its second. Lairs: Atta harvesters with soldiers
    /// and grubs in the big ones, Fithik, Treeback, Tree Mite, Maw, Warnet, Warden Bot, Xanx. Respawn 90 s
    /// posts and squads, 120 s camps and lairs, 180 s outposts. Pools on a control point arrive by Bane
    /// dropship. Generated by gen_world_spawns.py; world_spawns.csv has each row with its source.
    /// </summary>
    public class WorldSpawnpoolPreloader : PreloaderBase, IPreloader
    {
        public void Preload(MigrationBuilder migrationBuilder)
        {
            Insert(migrationBuilder, SpawnPoolEntry.TableName, typeof(SpawnPoolEntry));
        }

